/**
 * Gate A milestone A5: a corrupted node-predicate projection degrades and then recovers, rather than either answering
 * incompletely or failing forever.
 * <p>
 * The five steps are asserted in order in one test because they are one sequence, not five independent facts: a run
 * that degrades but never rebuilds passes the first three and is still the permanent-degradation bug that milestone A2
 * removed from the build path.
 */
class LmdbNodePredicateRecoveryTest {

	private TripleStore tripleStore;
	private LmdbDirectAdjacencyStore store;

	private static long uri(long payload) {
		return ValueIds.createId(ValueIds.T_URI, payload);
	}

	private static final long S1 = uri(1);
	private static final long S2 = uri(2);
	private static final long P1 = uri(100);
	private static final long P2 = uri(101);
	/** Present in the catalog (S2 uses it) but never on S1, and unsigned-after S1's own predicates. */
	private static final long P_ABSENT_ON_S1 = uri(900);
	private static final long O1 = uri(11);

	@BeforeEach
	void setUp(@TempDir File dataDir) throws Exception {
		tripleStore = new TripleStore(dataDir, new LmdbStoreConfig("spoc,posc"), null);
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbDirectAdjacencyOptions options = LmdbDirectAdjacencyOptions.resolve(config, 8L << 30,
				name -> LmdbDirectAdjacencyOptions.NODE_PREDICATE_PROJECTION_PROPERTY.equals(name) ? "true" : null, 4);
		System.setProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY, "true");
		store = new LmdbDirectAdjacencyStore(tripleStore, null, new AtomicBoolean(false), options);
		tripleStore.setDirectAdjacencyCommitHooks(store.commitListener(), store.newCommitDelta());

		tripleStore.startTransaction();
		tripleStore.storeTriple(S1, P1, O1, 0, true);
		tripleStore.storeTriple(S1, P2, O1, 0, true);
		tripleStore.storeTriple(S2, P_ABSENT_ON_S1, O1, 0, true);
		tripleStore.commit();
		store.applyCommitted(tripleStore.drainDirectAdjacencyCommitDelta());
	}

	@AfterEach
	void tearDown() throws Exception {
		LmdbNodePredicateIndex.clearCorruptionForTest();
		System.clearProperty(LmdbDirectAdjacencyStore.NODE_PREDICATE_SERVE_PROPERTY);
		if (store != null) {
			store.close();
		}
		if (tripleStore != null) {
			tripleStore.close();
		}
	}

	private List<long[]> enumerate(long subject) throws IOException {
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			RecordIterator it = store.tryOpen(view, null, subject, -1, -1, -1, true);
			if (it == null) {
				return null;
			}
			List<long[]> rows = new ArrayList<>();
			try {
				long[] quad;
				while ((quad = it.next()) != null) {
					rows.add(new long[] { quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX] });
				}
			} finally {
				it.close();
			}
			return rows;
		}
	}

	@Test
	void aCorruptedProjectionDegradesThenRecovers() throws Exception {
		// S1's projection row gains a predicate whose authoritative row does not exist.
		LmdbNodePredicateIndex.injectCorruptionForTest(LmdbAdjacencyPlane.PLANE_OUTGOING_EXPLICIT, S1,
				P_ABSENT_ON_S1);
		assertThat(store.buildNowForTest()).isTrue();
		assertThat(store.snapshotMetrics().nodePredicateInconsistencies).isZero();

		// The detection schedules a rebuild on the maintenance thread. Park that rebuild before it can publish, so the
		// degraded-window assertions below observe the degraded state deterministically instead of racing it.
		CountDownLatch rebuildReached = new CountDownLatch(1);
		CountDownLatch releaseRebuild = new CountDownLatch(1);
		store.afterBuildScanForTest = () -> {
			rebuildReached.countDown();
			try {
				assertThat(releaseRebuild.await(30, TimeUnit.SECONDS)).isTrue();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new IllegalStateException(e);
			}
		};

		// 1. The offending query fails rather than under-reporting. It cannot fall back: rows were already emitted.
		assertThatThrownBy(() -> enumerate(S1))
				.isInstanceOf(LmdbNodePredicateInconsistencyException.class)
				.hasMessageContaining("absent adjacency row");
		assertThat(store.snapshotMetrics().nodePredicateInconsistencies).isEqualTo(1);

		// 3. A rebuild really was scheduled: it is running right now, parked on the hook.
		assertThat(rebuildReached.await(30, TimeUnit.SECONDS)).as("a rebuild must be scheduled").isTrue();

		// 2. Subsequent queries decline instead of throwing. The gate itself is checked as well as the outcome,
		// because while the scheduled rebuild is parked the whole index is unavailable, so a null result on its own
		// would not distinguish "this capability is degraded" from "everything is temporarily gone".
		assertThat(store.nodePredicateServingEnabled()).as("the projection must stop serving on detection").isFalse();
		assertThat(enumerate(S1)).isNull();
		assertThat(enumerate(S2)).isNull();

		// 5. ...and the inconsistency counter does not tick once per fallback query: one fault, one count.
		assertThat(store.snapshotMetrics().nodePredicateInconsistencies).isEqualTo(1);

		// 4. The rebuild derives a fresh projection, and the shape serves again from it.
		LmdbNodePredicateIndex.clearCorruptionForTest();
		store.afterBuildScanForTest = null;
		releaseRebuild.countDown();
		assertThat(store.rebuildNowForTest()).isTrue();
		assertThat(store.publishedStateForTest().base().nodePredicateIndexOrNull()).isNotNull();
		assertThat(enumerate(S1)).extracting(row -> row[1]).containsExactly(P1, P2);
		assertThat(enumerate(S2)).extracting(row -> row[1]).containsExactly(P_ABSENT_ON_S1);
		assertThat(store.snapshotMetrics().nodePredicateInconsistencies).isEqualTo(1);
	}
}
